  const OUGH = [["through",["throuhg","thorugh"]],["thought",["thougth","thuoght"]],["enough",["enouhg","enogh"]],["rough",["rouhg","rogh"]],["cough",["couhg","cogh"]],["bought",["bougth","bouht"]],["brought",["brougth","broght"]],["though",["thouhg","thogh"]],["tough",["touhg","togh"]]];
