  const HOMO4 = [["I will see you next ___.","week",["weak"]],["He was too ___ to lift the box.","weak",["week"]],["Which hat will you ___?","wear",["where"]],["___ is my backpack?","Where",["Wear"]],["Please ___ the stick in half.","break",["brake"]],["Press the ___ to stop the bike.","brake",["break"]],["I was ___ with nothing to do.","bored",["board"]],["Write on the ___.","board",["bored"]],["She ___ the ball to me.","threw",["through"]],["We walked ___ the gate.","through",["threw"]],["I ___ the answer.","knew",["new"]],["I got a ___ bike.","new",["knew"]],["A boat has a ___.","sail",["sale"]],["The shoes are on ___.","sale",["sail"]],["I want to ___ a toy.","buy",["by"]],["Sit ___ me.","by",["buy"]]];
  const TRICKY = [["separate",["seperate","separat"]],["exercise",["excercise","exersize"]],["minute",["minite","minut"]],["sentence",["sentance","sentense"]],["disappear",["dissapear","disapear"]],["embarrass",["embarass","embarras"]],["calendar",["calender","calandar"]],["vegetable",["vegatable","vegetible"]],["grammar",["grammer","gramar"]],["necessary",["neccessary","necesary"]],["restaurant",["restaurent","resturant"]],["government",["goverment","govenment"]]];
  const PROOF = ["My [freind] came to play at my house.","We saw a [dolfin] jump in the sea.","I will [recieve] a gift on my birthday.","The [libary] is quiet and calm.","Please put the [peice] of paper on the desk.","That was a [wierd] noise in the night.","We ate [vegatables] with our dinner.","I like to [exersize] every morning.","Do we have [enuf] time to finish?","He [thaught] about the answer for a while.","The [grammer] lesson was fun.","We have art on [Wensday].","She wore a [diffrent] hat today."];
